import {specialist} from './workbenches.js';
import {modules,stages} from './catalog.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',data:'M4 4h16v16H4z M4 9h16 M9 9v11',map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 3v15 M15 6v15',logs:'M4 3v18 M12 3v18 M20 3v18 M4 6l3 3-2 3 3 3-4 3 M12 5l4 4-3 4 3 4-4 2',models:'m12 3 9 5-9 5-9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',decisions:'M12 3v18 M5 7l7-4 7 4 M5 17l7 4 7-4 M3 12h18',reports:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'m20 20-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',plus:'M12 4v16 M4 12h16',arrow:'M5 12h14 m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',upload:'M12 16V3 m-5 5 5-5 5 5 M4 15v6h16v-6',file:'M5 3h10l4 4v14H5z M14 3v5h5',close:'m6 6 12 12 M18 6 6 18',layers:'m12 3 9 5-9 5-9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',menu:'M4 6h16 M4 12h16 M4 18h16',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5z M10 21h4',download:'M12 3v13 m-5-5 5 5 5-5 M4 17v4h16v-4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',pin:'M12 21s7-7 7-12a7 7 0 0 0-14 0c0 5 7 12 7 12 M12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z',help:'M9 8a3 3 0 1 1 5 3c-2 1-2 2-2 3 M12 17h.01 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20'};
const icon=(n)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.logs}"/></svg>`;
const btn=(text,action,primary=false)=>`<button type="button" ${primary?'class="primary"':''} data-action="${action}">${text}</button>`;
const go=(id,text,primary=false)=>`<button type="button" ${primary?'class="primary"':''} data-go="${id}" aria-label="${text.includes('svg')?esc(modules.find(m=>m.id===id)?.name||stages.find(s=>s[0]===id)?.[1]||id):esc(text)}">${text}</button>`;
const badge=(text,color='green')=>`<span class="badge ${color}"><span class="dot"></span>${esc(text)}</span>`;
const demoWells=[{id:'TMB-01',x:235,y:225,depth:'10,450',curves:18,status:'Reviewed'},{id:'TMB-02',x:350,y:310,depth:'11,230',curves:24,status:'Reviewed'},{id:'TMB-04',x:510,y:175,depth:'12,680',curves:21,status:'Needs review'},{id:'TMB-05',x:610,y:320,depth:'10,840',curves:19,status:'Reviewed'},{id:'TMB-06',x:455,y:400,depth:'13,120',curves:32,status:'Reviewed'},{id:'TMB-07',x:690,y:200,depth:'12,460',curves:23,status:'Needs review'}];
const initial={project:'Tomboy field',well:'TMB-02',tab:'files',basemap:'Terrain',layers:{wells:true,paths:true,boundary:true,faults:false,grid:false},opacity:75,mapZoom:1,mapSelected:null,measurement:null,measurePoints:[],filters:'All',qcRecipe:'Despiking',qcDecision:null,qcPreview:false,scenario:'Base case',configs:{},audit:[],files:[],cutoffs:{vsh:35,phi:12,sw:60},reviews:[],savedLayouts:[],projects:['Tomboy field'],theme:'Light'};
let state;try{state={...initial,...JSON.parse(localStorage.getItem('stratax.frontend.v1')||'{}')};}catch{state={...initial};}
let portfolio;try{portfolio=JSON.parse(localStorage.getItem('stratax.projects.v2')||'null');}catch{}if(!portfolio?.records)portfolio={records:[{id:'tomboy-demo',name:'Tomboy field',description:'Legacy well interpretation and reservoir evaluation.',location:'Niger Delta, Nigeria',type:'Petrophysical evaluation',status:'Active',favorite:true,demo:true,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}],activeId:'tomboy-demo',contexts:{}};
if(portfolio.contexts[portfolio.activeId])state={...structuredClone(initial),...portfolio.contexts[portfolio.activeId]};
let wells=portfolio.records.find(p=>p.id===portfolio.activeId)?.demo?demoWells:[];
let projectQuery='',projectFilter='Active',projectView='grid',projectSort='recent';
function persistPortfolio(){localStorage.setItem('stratax.projects.v2',JSON.stringify(portfolio));}
function projectContext(){return portfolio.records.find(p=>p.id===portfolio.activeId);}
let fieldIndex=0;
let route=location.hash.slice(1)||'home',search='',formTab='Workbench';
const save=()=>{try{localStorage.setItem('stratax.frontend.v1',JSON.stringify(state));if(portfolio){portfolio.contexts[portfolio.activeId]=structuredClone(state);persistPortfolio();}}catch{toast('Local storage is full. Export your workspace to keep changes.');}};
function log(action){state.audit.unshift({action,time:new Date().toISOString(),well:state.well});save();}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function navigate(id){route=id;search='';formTab='Workbench';location.hash=id;render();window.scrollTo(0,0);}
const panel=(title,content,action='',subtitle='')=>`<section class="panel"><header class="panel-head"><div><h2>${title}</h2>${subtitle?`<small>${subtitle}</small>`:''}</div>${action}</header>${content}</section>`;
function heading(title,subtitle,actions='',eyebrow='WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function selectedNav(){if(['overview','map','data','reports','catalog','settings'].includes(route))return route;if(['files','wells','documents','digitize','collection'].includes(route))return'data';let m=modules.find(x=>x.id===route);if(m?.group==='Modeling'||m?.group==='Engineering'||route==='models')return'models';if(m?.group==='Decisions'||route==='decisions')return'decisions';return'interpretation';}
function render(){applyPreferences();if(['home','signin','signup','forgot-password'].includes(route)){renderPublicPage();return;}if(route==='projects'){renderProjects();return;}fieldIndex=0;let active=selectedNav();let title=modules.find(x=>x.id===route)?.name||({overview:'Overview',data:'Data',interpretation:'Interpretation',models:'Modeling & engineering',decisions:'Decisions',catalog:'Feature inventory',collection:'Data collection',qualitative:'Qualitative interpretation',quantitative:'Quantitative interpretation'}[route]||'Workspace');$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="logo.png" alt="StrataX logo"><div>StrataX<small>Subsurface workspace</small></div></div><button class="project-switch" data-action="projects">${icon('layers')}<span><strong>${esc(state.project)}</strong><small>Project workspace</small></span>${icon('down')}</button><nav class="nav" aria-label="Main navigation"><button data-go="projects">${icon('layers')}All projects</button><div class="label">Workspace</div>${[['overview','Overview','overview'],['data','Data','data'],['map','Map','map'],['interpretation','Interpretation','logs'],['models','Modeling & engineering','models'],['decisions','Decisions','decisions'],['reports','Reports','reports']].map(([id,t,i])=>`<button data-go="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}${t}${id==='data'?'<span class="nav-count">'+(currentSampleFiles().length+state.files.length)+'</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom">${profileMenu()}</div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><button class="mobile-menu icon" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${esc(title)}</strong></div><div class="top-actions"><button class="search-trigger" data-action="search">${icon('search')}<span class="search-label">Search wells, files, tools</span><span class="key">⌘ K</span></button><span class="demo-pill">${projectContext()?.demo?'DEMO DATA':'FRONTEND PREVIEW'}</span><button class="quiet icon" aria-label="Notifications" data-action="notifications">${icon('bell')}</button></div></header><div class="content">${state.downstreamStale&&['quantitative','cutoffs','summaries'].includes(route)?'<div class="note amber" style="margin-bottom:18px">An upstream QC decision changed. Downstream examples require revalidation when calculation services connect.</div>':''}${page()}<footer class="footer"><span>StrataX · Evidence-led subsurface interpretation</span><span>Frontend workspace · Changes saved in this browser</span></footer></div></main></div>`;bind();}
function page(){if(route==='overview')return overview();if(route==='map')return mapPage();if(['data','collection','files','wells','documents'].includes(route))return dataPage();if(route==='interpretation')return interpretation();if(route==='logs')return logsPage();if(route==='qc')return qcPage();if(route==='qualitative')return hub('Qualitative interpretation','Review geological and fluid indicators against supporting evidence.',modules.filter(m=>m.group==='Qualitative'));if(route==='quantitative')return hub('Quantitative interpretation','Build calibrated property evaluations from reviewed curves.',modules.filter(m=>m.group==='Quantitative'));if(route==='cutoffs')return cutoffsPage();if(route==='summaries')return summaries();if(route==='models')return hub('Modeling & engineering','Extend well evidence into spatial models and engineering studies.',modules.filter(m=>['Modeling','Engineering'].includes(m.group)));if(route==='decisions')return hub('Decisions','Compare scenarios and review candidate opportunities.',modules.filter(m=>m.group==='Decisions'));if(route==='reports')return reports();if(route==='reviews')return reviews();if(route==='settings')return settings();if(route==='catalog')return catalog();let m=modules.find(m=>m.id===route);return m?modulePage(m):overview();}
function overview(){if(!projectContext()?.demo)return newProjectOverview();return heading('Your field, in focus.','Review your evidence, resolve open items and continue interpretation.',btn(icon('upload')+'Import data','upload',true),esc(state.project.toUpperCase())+' / PROJECT OVERVIEW')+`<div class="stats">${[['Wells in project',String(wells.length).padStart(2,'0'),projectContext()?.demo?'Six demonstration wells':'No well evidence imported','pin'],['Source curves',projectContext()?.demo?'137':'0',projectContext()?.demo?'Illustrative inventory':'No curves imported','logs'],['Review items',projectContext()?.demo?'03':'0',projectContext()?.demo?'Two survey references · one curve':'No pending reviews','shield'],['Workflow progress',projectContext()?.demo?'1 / 6':'0 / 6',projectContext()?.demo?'Continue with QA/QC':'Start with data collection','layers']].map(([t,v,n,i])=>`<div class="stat"><div class="stat-top">${t}${icon(i)}</div><div class="stat-value">${v}</div><small class="${i==='layers'?'good':''}">${n}</small></div>`).join('')}</div><div class="grid"><div>${panel('Interpretation workflow',`<div class="workflow">${stages.map(([id,t,d],i)=>`<div class="flow-row"><span class="step-num ${projectContext()?.demo&&i<1?'done':''}">${projectContext()?.demo&&i<1?icon('check'):String(i+1).padStart(2,'0')}</span><div class="flow-text"><strong>${t}</strong><small>${d}</small></div>${badge(!projectContext()?.demo?'Not started':i===0?'Reviewed':i===1?'In review':'Not started',i===0?'green':i===1?'amber':'gray')}${go(id,icon('arrow'))}</div>`).join('')}</div>`,go('interpretation','View workspace '+icon('arrow')))}${panel('Wells at a glance',wellTable(wells.slice(0,4)),go('wells','All wells '+icon('arrow')))}</div><div>${panel('Field map',`<div class="mini-map">${mapArt()}<span class="map-foot">Illustrative geometry · Not survey coordinates</span></div>`,go('map','Open map '+icon('arrow')))}${panel('Needs your attention',`<div class="panel-body"><div class="activity"><div class="activity-dot">${icon('pin')}</div><div><p><strong>Confirm survey north reference</strong></p><small>TMB-04 and TMB-07 · Deviation surveys</small><div style="margin-top:8px">${go('trajectories','Review surveys '+icon('arrow'))}</div></div></div><div class="activity"><div class="activity-dot">${icon('logs')}</div><div><p><strong>Review a despiking proposal</strong></p><small>TMB-02 · Gamma ray</small><div style="margin-top:8px">${go('qc','Compare curves '+icon('arrow'))}</div></div></div></div>`)}${panel('Recent activity',`<div class="panel-body">${activityList(3)}</div>`,go('reviews','History'))}</div></div>`;}
function activityList(n=10){let a=state.audit.length?state.audit:[{action:'Opened the demonstration workspace',time:new Date().toISOString(),well:'TMB-02'},{action:'Example: source mapping reviewed',time:'2026-10-07T10:00:00Z',well:'TMB-01'}];return a.slice(0,n).map(x=>`<div class="activity"><div class="activity-dot">${icon('clock')}</div><div><p>${esc(x.action)}</p><small>${esc(x.well)} · ${new Date(x.time).toLocaleString(undefined,{timeZone:state.preferences?.timezone||'Africa/Lagos'})}</small></div></div>`).join('');}
function wellTable(list){return `<div class="table-wrap"><table><thead><tr><th>Well</th><th>Depth / ft MD</th><th>Curves</th><th>Review status</th><th></th></tr></thead><tbody>${list.map(w=>`<tr><td class="well-name">${w.id}</td><td class="mono">${w.depth}</td><td>${w.curves}</td><td>${badge(w.status,w.status==='Reviewed'?'green':'amber')}</td><td><button class="quiet icon" data-well="${w.id}" aria-label="Open ${w.id}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function mapArt(large=false){let l=state.layers;return `<div class="map-svg-wrap" style="transform:scale(${large?state.mapZoom:1})"><svg class="map-art" viewBox="0 0 900 550" preserveAspectRatio="xMidYMid slice" aria-label="Illustrative field map"><defs><pattern id="grid" width="80" height="80" patternUnits="userSpaceOnUse"><path d="M80 0H0V80" fill="none" stroke="#8fa499" stroke-width=".6"/></pattern></defs><rect width="900" height="550" fill="${state.basemap==='Blank'?'#f9fbf8':state.basemap==='Satellite'?'#506856':'#eaf0e5'}"/><g opacity="${state.basemap==='Blank'?0:1}"><path d="M0 0h900v140L670 170 570 100 340 180 210 80 0 140z" fill="#dce5d5"/><path d="m0 370 170-60 100 40 140-100 130 40 140-30 220 110v180H0z" fill="#d6e2d0"/><path d="m0 110 150 50 190-70 160 70 240-50 160 45M0 230l140-20 180 70 200-70 190 50 190-60M0 430l180-45 160 70 180-55 210 40 170-55" fill="none" stroke="#bdcdb6" stroke-width="1.3"/><path d="M0 260Q160 200 230 300T460 320T680 380T900 330" stroke="#afcdd0" stroke-width="15" fill="none"/><path d="m-20 450 200-180 230-30 260-190M410 240l160 170 340 90" stroke="#fffdf1" stroke-width="5" fill="none"/><path d="m-20 450 200-180 230-30 260-190M410 240l160 170 340 90" stroke="#cbd1bd" stroke-width="1" fill="none"/><text x="85" y="105" fill="#8b9f87" font-size="14" letter-spacing="3">${esc(state.project.toUpperCase())}</text></g>${l.boundary?`<path d="m150 145 435-70 190 125-60 250-355 40-200-175z" fill="#087f7410" stroke="#719884" stroke-width="1.3" stroke-dasharray="6 5"/>`:''}${l.grid?'<rect width="900" height="550" fill="url(#grid)"/>':''}${l.faults?'<path d="m340 80 70 150-40 200M550 100l-30 160 80 190" fill="none" stroke="#bb735e" stroke-width="3" stroke-dasharray="9 5"/>':''}${l.paths?`<g fill="none" stroke="#198779" stroke-width="2" opacity="${state.opacity/100}"><path d="M510 175q-35 15-65 65t-40 45"/><path d="M690 200q-70 10-90 50t-80 15"/></g>`:''}${l.wells?wells.map((w,i)=>`<g class="map-pin" data-mapwell="${w.id}" tabindex="0" role="button" aria-label="Select ${w.id}"><circle cx="${w.x}" cy="${w.y}" r="${state.mapSelected===w.id?18:12}" fill="#ffffffb0"/><circle cx="${w.x}" cy="${w.y}" r="6" fill="${i===2||i===5?'#bd8a40':'#08796d'}" stroke="white" stroke-width="2"/><text class="map-label" x="${w.x+17}" y="${w.y+4}">${w.id}</text></g>`).join(''):''}${state.measurePoints.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="5" fill="#c27538"/>`).join('')}${state.measurePoints.length>1?`<polyline points="${state.measurePoints.map(p=>`${p.x},${p.y}`).join(' ')}" fill="${state.measurement==='Area'?'#c2753822':'none'}" stroke="#c27538" stroke-width="2"/>`:''}<text x="850" y="55" font-size="12" fill="#446455">N</text><path d="m855 67-5 20h10z" fill="#446455"/></svg></div>`;}
function mapPage(){return heading('Map workspace','Explore wells and evidence in a shared spatial context.',btn(icon('plus')+'Add layer','add-layer')+btn('Review CRS','crs'))+`<div class="map-layout"><aside class="map-sidebar"><div class="label">Basemap</div><label class="field" style="margin-top:10px"><select id="basemap">${['Terrain','Street','Satellite','Blank'].map(x=>`<option ${state.basemap===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="note">Illustrative map backgrounds. Live tile providers connect during backend integration.</div><div class="label" style="margin-top:25px">Project layers</div>${[['wells','Well locations','6 demonstration wells'],['paths','Deviation surveys','2 illustrative paths'],['boundary','Field boundary','Demonstration polygon'],['faults','Interpreted faults','Example interpretation'],['grid','Field grid','Display only · CRS unconfirmed']].map(([id,t,d])=>`<label class="layer"><input type="checkbox" data-layer="${id}" ${state.layers[id]?'checked':''}><span>${t}<small>${d}</small></span></label>`).join('')}<label class="field" style="margin-top:20px">Survey opacity <input id="opacity" type="range" min="10" max="100" value="${state.opacity}"></label><div class="label" style="margin-top:25px">Well register</div>${wells.map(w=>`<button class="quiet" style="display:flex;width:100%;justify-content:space-between;padding:8px 0;font-size:10px" data-mapwell="${w.id}">${w.id}<span style="color:var(--muted)">${w.status==='Reviewed'?'Reviewed':'Provisional'}</span></button>`).join('')}</aside><div class="mini-map map-large" id="map-surface">${mapArt(true)}<div class="map-tools">${btn(icon('pin')+'Fit wells','fit')}${btn('Distance','measure-distance')}${btn('Area','measure-area')}${state.measurement?btn('Clear','measure-clear'):''}</div><div class="map-controls"><button data-action="zoom-in" aria-label="Zoom in">+</button><button data-action="zoom-out" aria-label="Zoom out">−</button></div><div class="map-foot">Illustrative geometry · ${state.measurement?`${state.measurement}: ${state.measurePoints.length} points, screen measurement only`:'Scale unavailable without georeferenced data'}</div>${state.mapSelected?`<div class="map-detail"><h3>${state.mapSelected}</h3>${badge(state.mapSelected==='TMB-04'||state.mapSelected==='TMB-07'?'Survey reference unconfirmed':'Example location','amber')}<p>Demonstration position. Confirm source coordinates and CRS before spatial calculations.</p>${go('logs','Open well logs '+icon('arrow'))}</div>`:''}</div></div><div class="legend" style="margin:15px 0 22px"><span><i style="background:#08796d"></i>Well</span><span><i style="background:#bd8a40"></i>Review required</span><span><i style="background:#198779"></i>Survey path</span><span><i style="background:#bb735e"></i>Fault interpretation</span></div>`;}
const demoFiles=[{name:'TMB-02_plan.las',type:'Well logs',well:'TMB-02',status:'Reviewed',size:'1.8 MB'},{name:'TMB-04_survey.asc',type:'Deviation',well:'TMB-04',status:'Needs mapping',size:'18 KB'},{name:'Well_headers.xlsx',type:'Well headers',well:'Multiple',status:'Reviewed',size:'42 KB'},{name:'Formation_tops.csv',type:'Well tops',well:'Multiple',status:'Reviewed',size:'12 KB'},{name:'Core_analysis.xlsx',type:'Core data',well:'Unassigned',status:'Needs mapping',size:'88 KB'},{name:'Legacy_completion_report.pdf',type:'Reports',well:'TMB-02',status:'Evidence only',size:'2.1 MB'}];
function currentSampleFiles(){return projectContext()?.demo?demoFiles:[];}
function dataPage(){let tab=['files','wells','documents'].includes(route)?route:state.tab;let tabs=[['files','Source files'],['wells','Well register'],['documents','Document library']];let files=[...currentSampleFiles(),...state.files];return heading('Data collection','Bring every source into a reviewed, well-linked evidence catalogue.',btn(icon('upload')+'Import data','upload',true))+`<div class="tabs">${tabs.map(([id,t])=>`<button class="${id===tab?'active':''}" data-datatab="${id}">${t}</button>`).join('')}</div>`+(tab==='wells'?panel('Well register',`<div class="toolbar"><input id="filter-data" placeholder="Find a well…" aria-label="Find a well" value="${esc(search)}">${btn('Add well','add-well')}</div>${wellTable(wells.filter(w=>w.id.toLowerCase().includes(search.toLowerCase())))}`):tab==='documents'?panel('Legacy document catalogue',`<div class="toolbar"><input id="filter-data" placeholder="Search document names or well IDs…" value="${esc(search)}" aria-label="Search documents"><select id="doc-family" aria-label="Document family">${['All','Well logs','Drilling logs','Reports','Geochemistry','Maps'].map(t=>`<option ${state.filters===t?'selected':''}>${t}</option>`).join('')}</select>${go('digitize','Digitize a log')}</div><div class="panel-body"><div class="note">Filename search works locally. Semantic retrieval and OCR will require connected services. No extracted text is implied.</div></div>${fileTable(files.filter(f=>(f.name+' '+f.well).toLowerCase().includes(search.toLowerCase())&&(state.filters==='All'||f.type===state.filters)))}`):panel('Source inventory',`<div class="toolbar"><input id="filter-data" placeholder="Search files or well IDs…" aria-label="Search files" value="${esc(search)}"><span class="badge gray">${files.length} files</span>${btn('Export inventory','export-files')}</div>${fileTable(files.filter(f=>(f.name+' '+f.well).toLowerCase().includes(search.toLowerCase())))}`))+`<div class="note" style="margin-bottom:20px">Demonstration records are separate from local uploads. Local file selection stores metadata only; no scientific parsing or server upload takes place.</div>`;}
function fileTable(files){return `<div class="table-wrap"><table><thead><tr><th>File name</th><th>Category</th><th>Well</th><th>Status</th><th>Size</th><th></th></tr></thead><tbody>${files.length?files.map(f=>`<tr><td>${icon('file')} <span class="well-name">${esc(f.name)}</span></td><td>${esc(f.type)}</td><td>${esc(f.well)}</td><td>${badge(f.status,f.status==='Reviewed'?'green':f.status==='Needs mapping'?'amber':'gray')}</td><td class="mono">${esc(f.size)}</td><td><button data-file="${esc(f.name)}">Review</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No matching files.</td></tr>'}</tbody></table></div>`;}
function cards(list){return `<div class="module-grid">${list.map(m=>`<button class="module-card" data-go="${m.id}"><span class="module-icon">${icon(m.group==='Spatial'?'map':m.group==='Modeling'?'models':'logs')}</span><h3>${m.name}</h3><p>${m.description}</p><span class="badge gray">${m.features.length} feature groups</span></button>`).join('')}</div>`;}
function hub(t,d,list){return heading(t,d)+cards(list);}
function interpretation(){return heading('Interpretation workspace','A clear path from reviewed evidence to reservoir evaluation.',go('logs',icon('logs')+'Open log viewer',true))+`<div class="module-grid" style="margin-bottom:22px">${stages.map(([id,t,d],i)=>`<button class="module-card" data-go="${id}"><span class="module-icon">${String(i+1).padStart(2,'0')}</span><h3>${t}</h3><p>${d}</p>${badge(!projectContext()?.demo?'Not started':i===0?'Reviewed':i===1?'In review':'Not started',i===0?'green':i===1?'amber':'gray')}</button>`).join('')}</div>${panel('Advanced workspaces',`<div class="panel-body">${cards(modules.filter(m=>m.group==='Advanced'))}</div>`)}`;}
function stepper(id){return `<div class="stepper">${stages.map(([x,t],i)=>`<button data-go="${x}" class="${id===x?'active':''}"><span>0${i+1}</span> ${['Collection','QA/QC','Qualitative','Quantitative','Cutoffs','Summaries'][i]}</button>`).join('')}</div>`;}
function wellSelect(){return `<select id="well-select" aria-label="Selected well">${wells.map(w=>`<option ${w.id===state.well?'selected':''}>${w.id}</option>`).join('')}</select>`;}
function chart(qc=false){let colors=['#b18b35','#168c78','#9c6f9e','#589bb5'];let lines=colors.map((c,i)=>{let points=[];for(let n=0;n<=170;n++){let raw=(Math.sin(n*.18+i*2)*.22+Math.sin(n*.63+i)*.12+Math.cos(n*.045+i)*.17+.5);let val=raw;if(qc&&i===0&&n===74)val=.98;points.push(`${75+i*150+val*105},${23+n*2.1}`);}return `<polyline fill="none" stroke="${c}" stroke-width="1.3" points="${points.join(' ')}"/>${qc&&i===0&&state.qcPreview?`<polyline fill="none" stroke="#087f74" stroke-width="1.6" stroke-dasharray="4 2" points="${points.filter((_,j)=>j!==74).join(' ')}"/>`:''}`;}).join('');return `<svg class="log-chart" viewBox="0 0 720 410" role="img" aria-label="Synthetic demonstration log curves"><defs><pattern id="loggrid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#e7ece7" stroke-width=".6"/></pattern></defs><rect x="65" y="15" width="620" height="370" fill="url(#loggrid)"/>${[65,215,365,515,685].map(x=>`<path d="M${x} 15v370" stroke="#cfdcd2"/>`).join('')}${[4200,4250,4300,4350,4400,4450,4500].map((d,i)=>`<text x="10" y="${30+i*57}" fill="#819087" font-size="10">${d}</text><path d="M65 ${27+i*57}h620" stroke="#dae4dc"/>`).join('')}<rect x="65" y="170" width="620" height="55" fill="#d5e9d015"/>${lines}<path d="M65 200h620" stroke="#90b4a3" stroke-dasharray="5 5"/><text x="620" y="195" fill="#769683" font-size="9">Zone A</text></svg>`;}
function logsPage(){return heading('Log viewer & correlation','Inspect well curves and pick interpretation intervals.',btn('Save layout','save-layout')+btn('Add track','add-track'))+`<div class="panel"><div class="toolbar">${wellSelect()}<label>Depth <select id="depth-view" aria-label="Depth view"><option>MD / ft</option><option>TVD / ft</option><option>TVDSS / ft</option></select></label>${btn('Markers','markers')}${btn('Display settings','display')}<span class="badge gray">Synthetic example curves</span></div><div class="workbench"><div><div class="chart-header"><span>DEPTH / FT</span><span>GR · 0–150 gAPI</span><span>RT · 0.2–2000 Ω·m</span><span>RHOB · 1.95–2.95</span><span>NPHI · 0.45–−0.15</span></div>${chart()}<div class="toolbar"><span class="legend">${['Gamma ray','Resistivity','Density','Neutron'].map((t,i)=>`<span><i style="background:${['#b18b35','#168c78','#9c6f9e','#589bb5'][i]}"></i>${t}</span>`).join('')}</span></div></div><aside class="inspector"><div class="label">Well inspector</div><h2 style="margin:14px 0">${state.well}</h2><div class="status-row"><span>Curve source</span><strong>Demo</strong></div><div class="status-row"><span>Depth window</span><span>4,200–4,500 ft</span></div><div class="status-row"><span>Reference</span><span>MD</span></div><div class="toggle-list">${['Show grid','Show formation markers','Synchronize depth','Show curve fills'].map(t=>`<label>${t}<input type="checkbox" checked></label>`).join('')}</div><div style="margin-top:20px">${btn('Compare wells','compare-wells')}</div><div class="note" style="margin-top:20px">TVD and TVDSS require reviewed survey and datum data. Switching display controls here does not calculate a depth conversion.</div></aside></div></div>`;}
function qcPage(){return heading('QA/QC & repairs','Compare corrections before accepting a new curve version.',go('reviews','Review history'))+stepper('qc')+`<div class="panel"><div class="toolbar">${wellSelect()}<select id="recipe-select" aria-label="Conditioning recipe">${['Despiking','Interpolation','Smoothing','Normalization','Depth shift','Splicing','Environmental correction'].map(x=>`<option ${state.qcRecipe===x?'selected':''}>${x}</option>`).join('')}</select>${badge(state.qcDecision||'Not reviewed',state.qcDecision==='Accepted'?'green':'amber')}</div><div class="workbench"><div><div class="chart-header"><span>DEPTH / FT</span><span>GR ORIGINAL</span><span>RESISTIVITY</span><span>DENSITY</span><span>NEUTRON</span></div>${chart(true)}<div class="toolbar"><span class="legend"><span><i style="background:#b18b35"></i>Original</span>${state.qcPreview?'<span><i style="background:#087f74"></i>Proposed example</span>':''}</span></div><div class="panel-body"><div class="note">Synthetic comparison for interface review. Preview does not apply a scientific correction to imported files.</div></div></div><aside class="inspector"><div class="label">${state.qcRecipe} settings</div><form id="qc-form" style="margin-top:20px">${state.qcRecipe==='Normalization'?field('Clean endpoint (gAPI)','25')+field('Shale endpoint (gAPI)','120'):state.qcRecipe==='Depth shift'?field('Shift (ft)','0'):field(state.qcRecipe==='Interpolation'?'Maximum gap (ft)':'Window (odd samples)','7')+field('Threshold','3')}<label class="field">Depth interval<input value="4200–4500 ft" required></label><label class="layer"><input type="checkbox" checked>Respect nulls and depth breaks</label><button class="primary" type="submit">Preview comparison</button></form>${state.qcPreview?`<div style="margin-top:22px"><div class="note amber">Review the demonstration proposal. Acceptance records a local UI decision only.</div><div class="actions" style="margin-top:14px">${btn('Accept','qc-accept',true)}${btn('Reject','qc-reject')}</div></div>`:''}</aside></div></div>`;}
function field(label,value,index=fieldIndex++){let opts=value.includes('|');return `<label class="field">${esc(label)}${opts?`<select name="f${index}">${value.split('|').map(v=>`<option>${esc(v)}</option>`).join('')}</select>`:`<input name="f${index}" value="${esc(value)}" placeholder="${value?'':'Required for calculation'}">`}</label>`;}
function modulePage(m){let vals=state.configs[m.id]?.values;return heading(m.name,m.description,btn('Save configuration','save-module',true))+(['Qualitative','Quantitative'].includes(m.group)?stepper(m.group==='Qualitative'?'qualitative':'quantitative'):'')+`<div class="tabs">${['Workbench','Parameters','Inputs & evidence','Results','Features'].map(t=>`<button class="${formTab===t?'active':''}" data-formtab="${t}">${t}</button>`).join('')}</div>`+(formTab==='Workbench'?specialist(m,state):formTab==='Features'?panel('Included feature groups',`<div class="panel-body">${m.features.map(t=>`<div class="status-row"><span>${t}</span><button data-feature="${esc(t)}">Configure</button></div>`).join('')}<p class="sub" style="margin-top:15px">This inventory tracks frontend coverage, not computational availability.</p></div>`):formTab==='Inputs & evidence'?panel('Input contract',`<div class="panel-body"><div class="note amber">No calculation service or authoritative datasets are connected. Source selection here is a frontend configuration.</div><form id="module-inputs" style="margin-top:20px"><div class="form-grid">${field('Well',wells.map(w=>w.id).join('|'))}${field('Evidence source','Not connected|Reviewed curve version|Core dataset|External reference')}${field('Depth reference','MD|TVD|TVDSS')}${field('Source version ID','')}</div><button type="submit">Save input selection</button></form></div>`):formTab==='Results'?panel('Results',`<div class="empty">${icon('logs')}<strong>Awaiting a connected calculation service</strong><p>Saved settings are ready for integration. No ${m.name.toLowerCase()} results have been calculated.</p>${btn('View saved configuration','view-config')}</div>`):`<div class="grid"><section class="panel"><header class="panel-head"><h2>Evaluation settings</h2>${badge(state.configs[m.id]?'Draft saved':'Not configured','gray')}</header><div class="panel-body"><form id="module-form"><div class="form-grid">${(m.fields||[['Scenario name','Base case'],['Input dataset','Not connected']]).map(([k,v],i)=>field(k,vals?.[i]&&v.includes('|')?[vals[i],...v.split('|').filter(x=>x!==vals[i])].join('|'):vals?.[i]??v,i)).join('')}</div><label class="field">Interpretation notes<textarea name="notes" placeholder="Record assumptions and supporting references…">${esc(state.configs[m.id]?.notes||'')}</textarea></label><div class="actions"><button class="primary" type="submit">Save configuration</button>${btn('Duplicate scenario','duplicate')}</div></form></div></section><div>${panel('Evidence requirements',`<div class="panel-body"><div class="note amber">Calculation unavailable until input versions, units, method applicability and required calibration evidence are validated by the backend.</div>${m.features.slice(0,4).map(t=>`<div class="status-row"><span>${t}</span>${badge('Review needed','gray')}</div>`).join('')}</div>`)}${panel('Provenance',`<div class="panel-body"><div class="status-row"><span>Role</span><strong>Draft configuration</strong></div><div class="status-row"><span>Original sources</span><span>Preserved</span></div><div class="status-row"><span>Calculation</span><span>Not run</span></div>${go('reviews','Open version history')}</div>`)}</div></div>`);}
function cutoffsPage(){let c=state.cutoffs;return heading('Cutoff determination','Define explicit reservoir and pay rules for each zone.',btn('Save cutoff version','save-cutoffs',true))+stepper('cutoffs')+`<div class="grid">${panel('Reservoir & pay criteria',`<div class="panel-body"><div class="note" style="margin-bottom:20px">Thresholds below demonstrate UI sensitivity on a synthetic 300 ft interval. They are not field evaluation results.</div><label class="field">Maximum shale volume <strong>${c.vsh}%</strong><input type="range" id="cut-vsh" min="5" max="80" value="${c.vsh}"></label><label class="field">Minimum effective porosity <strong>${c.phi}%</strong><input type="range" id="cut-phi" min="2" max="35" value="${c.phi}"></label><label class="field">Maximum water saturation <strong>${c.sw}%</strong><input type="range" id="cut-sw" min="10" max="95" value="${c.sw}"></label><div class="form-grid">${field('Rule combination','AND|OR')}${field('Missing-value policy','Unknown / excluded|Fail criterion')}${field('Zone','Zone A|Zone B|All zones')}${field('Minimum bed thickness (ft)','0')}</div><div class="note">Net reservoir: shale and porosity criteria. Net pay adds the saturation criterion. Permeability can be added when validated.</div></div>`)}<div>${panel('Sensitivity preview',`<div class="panel-body"><span class="badge gray">Synthetic example</span><div class="metric-strip"><div><small>Illustrative net reservoir</small><strong>${Math.round(300*(c.vsh/100)*(1-c.phi/100))} ft</strong></div><div><small>Illustrative net pay</small><strong>${Math.round(300*(c.vsh/100)*(1-c.phi/100)*(c.sw/100))} ft</strong></div></div><p class="sub">This simple UI response tests threshold controls. It is not a petrophysical algorithm.</p></div>`)}${panel('Decision rationale',`<div class="panel-body"><label class="field">Supporting evidence<textarea id="cutoff-note" placeholder="Core, test results, calibration or interpretation rationale…">${esc(state.cutoffNote||'')}</textarea></label>${go('summaries','Open reservoir summaries '+icon('arrow'))}</div>`)}</div></div>`;}
function summaries(){return heading('Reservoir sums & averages','Inspect definitions, data coverage and zone-level properties.',btn(icon('download')+'Export example CSV','export-summary'))+stepper('summaries')+`<div class="note amber" style="margin-bottom:20px">All numbers in this screen are synthetic examples. No imported well has been evaluated.</div><div class="panel"><div class="toolbar">${wellSelect()}${field('Thickness basis','MD|Vertical|Stratigraphic')}${btn('Definitions','definitions')}${btn('Compare scenarios','compare-scenarios')}</div><div class="table-wrap"><table><thead><tr><th>Zone</th><th>Gross / ft</th><th>Evaluated / ft</th><th>Net res. / ft</th><th>Net pay / ft</th><th>NTG</th><th>Mean PHIE</th><th>Mean Sw</th></tr></thead><tbody>${[['A',120,114,65,40,'.54','.18','.42'],['B',95,90,46,25,'.48','.16','.48'],['C',85,76,38,18,'.45','.14','.51']].map(row=>`<tr>${row.map((v,i)=>`<td ${i===0?'class="well-name"':''}>${i===0?'Zone ':''}${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panel-body"><div class="note">NTG uses gross interval thickness in this example. Property averages use net-reservoir sample thickness. Missing sections remain outside evaluated coverage.</div></div></div>${panel('Aggregation controls',`<div class="panel-body form-grid">${field('Group by','Well and zone|Formation|Field')}${field('Permeability average','Arithmetic|Geometric|Harmonic')}${field('Missing interval treatment','Show separately / never assume zero')}${field('Output properties','PHIE, Sw, Vsh, φh, HCPH, kh')}</div>`)}`;}
function reports(){return heading('Reports & exports','Assemble reviewed results with their methods and source references.',btn('Configure sections','report-sections')+btn(icon('download')+'Print / save PDF','print',true))+`<div class="report-paper"><div class="brand" style="padding:0"><img src="logo.png" alt=""><span>StrataX</span></div><div class="eyebrow" style="margin-top:35px">DEMONSTRATION REPORT / UNAPPROVED</div><h2>${esc(state.project)}<br>Petrophysical evaluation</h2><p>This frontend report demonstrates structure and evidence traceability. No field results have been calculated or scientifically approved.</p><div class="status-row"><span>Selected well</span><strong>${state.well}</strong></div><div class="status-row"><span>Scenario</span><span>${esc(state.scenario)}</span></div><div class="status-row"><span>Local review state</span>${badge('Draft','amber')}</div>${(state.reportSections||['Evidence inventory','QA/QC decisions','Interpretation methods','Reservoir summaries','Limitations & provenance']).map((s,i)=>`<section><h3 style="font-size:15px;margin-top:30px">${i+1}. ${esc(s)}</h3><p>${s==='QA/QC decisions'?`Local proposal state: ${esc(state.qcDecision||'Not reviewed')}. Original sources remain unchanged.`:s==='Interpretation methods'?`${Object.keys(state.configs).length} local configuration drafts saved. Calculation inputs and reference validation remain pending.`:'This section will draw from versioned, reviewer-accepted project evidence once connected. No unsupported result is inserted.'}</p></section>`).join('')}<p style="border-top:1px solid var(--line);padding-top:20px;margin-top:30px;font-size:10px">Prepared in StrataX · Frontend demonstration · Source and figure links await connected evidence.</p></div>`;}
function reviews(){return heading('Reviews & history','Follow local decisions and inspect saved configuration versions.',btn('Export workspace','export-workspace'))+`<div class="grid">${panel('Activity timeline',`<div class="panel-body">${activityList(30)}</div>`)}${panel('Saved configurations',`<div class="panel-body">${Object.keys(state.configs).length?Object.entries(state.configs).map(([id,c])=>`<div class="version"><div>${icon('file')}</div><div><strong>${esc(modules.find(m=>m.id===id)?.name||id)}</strong><p>Version ${c.version} · Draft only</p>${go(id,'Open configuration')}</div></div>`).join(''):'<div class="empty"><strong>No configurations saved yet</strong>Open an interpretation tool to define a draft.</div>'}</div>`)}</div>`;}
function settings(){let pref=state.preferences||{},val=(k,d)=>pref[k]??d;let select=(k,t,opts,d)=>`<label class="field">${t}<select name="${k}">${opts.map(v=>`<option ${val(k,d)===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;let input=(k,t,d)=>`<label class="field">${t}<input name="${k}" value="${esc(val(k,d))}"></label>`;let toggle=(k,t,d=true)=>`<label class="setting-toggle"><span>${t}</span><input name="${k}" type="checkbox" ${val(k,d)?'checked':''}></label>`;return heading('Settings','Set up your project and make the workspace feel like yours.',btn('Save preferences','save-settings',true))+`<form id="settings-form"><div class="settings-layout"><nav class="settings-index" aria-label="Settings sections">${['Profile','Project','Appearance','Units & references','Log viewer','Map defaults','Workflow & reviews','Notifications','Exports','Data & access'].map((t,i)=>`<a href="#" data-settingsection="settings-${i}">${t}</a>`).join('')}</nav><div><section class="panel" id="settings-0"><header class="panel-head"><h2>Profile & identity</h2></header><div class="panel-body"><div class="profile-preview"><div class="avatar">${profileInitials()}</div><div><strong>${esc(profileName())}</strong><small>Project owner · Frontend profile</small></div></div><div class="form-grid">${input('displayName','Display name','TerraCode Analytics')}${input('jobTitle','Role / title','Petrophysicist')}${input('organization','Organization','TerraCode Analytics Limited')}${select('timezone','Display timezone',['Africa/Lagos','UTC','Europe/London'],'Africa/Lagos')}</div></div></section><section class="panel" id="settings-1"><header class="panel-head"><h2>Project details</h2></header><div class="panel-body"><div class="form-grid">${field('Project name',state.project,0)}${input('projectCode','Project code','')}${input('basin','Basin / region',projectContext()?.location||'')}${select('formationProfile','Formation profile',['Young clastic','Old clastic','Carbonate','Mixed / custom'],'Young clastic')}</div><label class="field">Project notes<textarea name="notes">${esc(state.projectNotes||'')}</textarea></label></div></section><section class="panel" id="settings-2"><header class="panel-head"><h2>Appearance & accessibility</h2></header><div class="panel-body"><div class="form-grid">${select('density','Interface density',['Comfortable','Compact'],'Comfortable')}${select('fontSize','Text size',['Standard','Large'],'Standard')}${select('accent','Accent color',['Teal','Forest'],'Teal')}${select('startPage','Workspace start page',['Projects','Overview'],'Projects')}</div>${toggle('reducedMotion','Reduce animations',false)}<p class="note">Density, text size, accent and motion preferences apply to this browser.</p></div></section><section class="panel" id="settings-3"><header class="panel-head"><h2>Units & coordinate references</h2></header><div class="panel-body form-grid">${select('depthUnit','Depth unit',['Feet','Metres'],'Feet')}${select('depthReference','Depth reference',['MD','TVD','TVDSS'],'MD')}${select('porosityUnit','Porosity display',['Fraction','Percent'],'Fraction')}${select('pressureUnit','Pressure',['psi','bar','MPa'],'psi')}${input('horizontalCRS','Horizontal CRS / EPSG','Unconfirmed')}${input('verticalDatum','Vertical datum','Unconfirmed')}</div><div class="panel-body"><p class="note">Unit and CRS defaults are configuration preferences. They do not convert existing evidence or confirm source references.</p></div></section><section class="panel" id="settings-4"><header class="panel-head"><h2>Log viewer defaults</h2></header><div class="panel-body"><div class="form-grid">${select('viewerTemplate','Default template',['Triple combo','Petrophysics','Correlation','Custom'],'Triple combo')}${select('depthDirection','Depth direction',['Increasing downward','Increasing upward'],'Increasing downward')}${select('trackWidth','Track width',['Standard','Wide','Narrow'],'Standard')}${select('curveThickness','Curve line weight',['Fine','Standard','Bold'],'Standard')}</div>${toggle('linkedDepth','Link depth across wells')}${toggle('gridDefault','Show log grid by default')}</div></section><section class="panel" id="settings-5"><header class="panel-head"><h2>Map defaults</h2></header><div class="panel-body form-grid">${select('mapDefault','Preferred basemap',['Terrain','Street','Satellite','Blank'],'Terrain')}${select('mapUnits','Measurement units',['Metric','Imperial'],'Metric')}${select('wellLabels','Well label visibility',['Always','Selected only','Hidden'],'Always')}${select('coordinateFormat','Coordinate format',['Decimal degrees','Degrees minutes seconds','Projected coordinates'],'Decimal degrees')}</div></section><section class="panel" id="settings-6"><header class="panel-head"><h2>Workflow & review</h2></header><div class="panel-body"><div class="form-grid">${select('approvalPolicy','Review policy',['Explicit reviewer acceptance','Draft comparison only'],'Explicit reviewer acceptance')}${select('nullPolicy','Missing-data policy',['Preserve and flag','Exclude with reason'],'Preserve and flag')}${select('versionLabel','Version naming',['Automatic sequence','Date and sequence'],'Automatic sequence')}${select('stalePolicy','Changed-input behavior',['Flag downstream results','Require re-review'],'Flag downstream results')}</div><p class="note">These configure the intended workflow. Scientific approvals and policy enforcement require the backend.</p></div></section><section class="panel" id="settings-7"><header class="panel-head"><h2>Notifications</h2></header><div class="panel-body">${toggle('notifications','Show in-app notifications')}${toggle('reviewAlerts','Highlight pending reviews')}<div class="form-grid" style="margin-top:18px">${select('digest','Future email digest',['Off','Daily','Weekly'],'Off')}${select('notificationScope','Notification scope',['My projects','Assigned to me'],'My projects')}</div><p class="note">No email is sent from this preview.</p></div></section><section class="panel" id="settings-8"><header class="panel-head"><h2>Reports & exports</h2></header><div class="panel-body form-grid">${select('paperSize','Paper size',['A4','Letter','A3'],'A4')}${select('reportOrientation','Report orientation',['Portrait','Landscape'],'Portrait')}${select('decimalPlaces','Decimal precision',['2','3','4','6'],'3')}${select('dataExport','Default data format',['CSV','JSON','LAS'],'CSV')}${input('reportAuthor','Report author',profileName())}${select('reportAppendix','Provenance appendix',['Include','Exclude from draft'],'Include')}</div></section><section class="panel" id="settings-9"><header class="panel-head"><h2>Data portability & access</h2></header><div class="panel-body"><p class="sub">Local drafts are stored separately for each project. Server access and invitation enforcement will connect later.</p><div class="actions" style="margin-top:18px">${btn('Export workspace','export-workspace')}${btn('Permission matrix','permissions')}${btn('Reset demo state','reset')}</div></div></section><div class="settings-save"><button type="submit" class="primary">Save all preferences</button><span>Saved in this browser</span></div></div></div></form>`;}

function catalog(){return heading('Complete feature inventory',`${modules.length} workspaces covering the agreed product scope. Coverage describes interface status, not scientific implementation.`,btn(icon('download')+'Export inventory','export-catalog'))+`<div class="panel"><div class="toolbar"><input id="catalog-search" aria-label="Filter feature inventory" placeholder="Find a workspace or microfeature…" value="${esc(search)}"><span class="badge gray">${modules.reduce((a,m)=>a+m.features.length,0)} feature groups</span></div><div class="table-wrap"><table class="catalog-table"><thead><tr><th>Area</th><th>Workspace</th><th>Microfeatures specified</th><th>Interface coverage</th><th></th></tr></thead><tbody>${modules.filter(m=>(m.name+' '+m.group+' '+m.features.join(' ')).toLowerCase().includes(search.toLowerCase())).map(m=>`<tr><td>${m.group}</td><td class="well-name">${m.name}</td><td>${m.features.map(esc).join(' · ')}</td><td>${badge(['files','wells','documents','map','logs','qc','cutoffs','summaries','reports','reviews','settings'].includes(m.id)?'Interactive workspace':'Configuration + requirements','gray')}</td><td>${go(m.id,'Open '+icon('arrow'))}</td></tr>`).join('')}</tbody></table></div></div>`;}
function modal(title,body,footer=''){let d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="quiet icon" data-close aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;d.showModal();d.querySelector('[data-close]').onclick=()=>d.close();d.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{d.close();navigate(b.dataset.go);});}
function download(name,data,type='application/json'){let blob=new Blob([data],{type});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function saveModule(){let m=modules.find(x=>x.id===route),form=$('#module-form');if(!m)return;if(!form){formTab='Parameters';render();toast('Edit parameters, then save the configuration.');return;}let data=new FormData(form);state.configHistory=state.configHistory||{};state.configHistory[m.id]=state.configHistory[m.id]||[];if(state.configs[m.id])state.configHistory[m.id].push(structuredClone(state.configs[m.id]));state.configs[m.id]={values:(m.fields||[1,2]).map((_,i)=>String(data.get('f'+i)||'')),notes:data.get('notes'),version:(state.configs[m.id]?.version||0)+1,updatedAt:new Date().toISOString()};log(`Saved ${m.name} configuration`);toast('Configuration saved locally. No calculation has been run.');render();}
function bind(){bindWorkbench();document.querySelectorAll('[data-settingsection]').forEach(a=>a.onclick=e=>{e.preventDefault();$('#'+a.dataset.settingsection)?.scrollIntoView({behavior:'smooth',block:'start'});});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-well]').forEach(b=>b.onclick=()=>{state.well=b.dataset.well;save();navigate('logs');});document.querySelectorAll('[data-mapwell]').forEach(b=>{b.onclick=e=>{e.stopPropagation();state.mapSelected=b.dataset.mapwell;state.well=b.dataset.mapwell;save();if(route==='map')render();else navigate('map');};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')b.click();};});document.querySelectorAll('[data-layer]').forEach(b=>b.onchange=()=>{state.layers[b.dataset.layer]=b.checked;save();render();});document.querySelectorAll('[data-datatab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.datatab;state.filters='All';save();navigate(b.dataset.datatab);});document.querySelectorAll('[data-formtab]').forEach(b=>b.onclick=()=>{formTab=b.dataset.formtab;render();});document.querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>featureEditor(b.dataset.feature));document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>fileReview(b.dataset.file));if($('#well-select'))$('#well-select').onchange=e=>{state.well=e.target.value;save();render();};if($('#basemap'))$('#basemap').onchange=e=>{state.basemap=e.target.value;save();render();};if($('#opacity'))$('#opacity').onchange=e=>{state.opacity=+e.target.value;save();render();};if($('#map-surface'))$('#map-surface').onclick=e=>{if(!state.measurement||e.target.closest('button')||e.target.closest('[data-mapwell]'))return;let r=$('#map-surface').getBoundingClientRect();state.measurePoints.push({x:(e.clientX-r.left)/r.width*900,y:(e.clientY-r.top)/r.height*550});save();render();};for(let id of ['filter-data','catalog-search'])if($('#'+id))$('#'+id).oninput=e=>{let pos=e.target.selectionStart;search=e.target.value;render();let el=$('#'+id);el.focus();el.setSelectionRange(pos,pos);};if($('#doc-family'))$('#doc-family').onchange=e=>{state.filters=e.target.value;save();render();};if($('#recipe-select'))$('#recipe-select').onchange=e=>{state.qcRecipe=e.target.value;state.qcPreview=false;state.qcDecision=null;save();render();};if($('#qc-form'))$('#qc-form').onsubmit=e=>{e.preventDefault();state.qcPreview=true;log('Opened demonstration '+state.qcRecipe.toLowerCase()+' preview');render();};if($('#module-form'))$('#module-form').onsubmit=e=>{e.preventDefault();saveModule();};if($('#module-inputs'))$('#module-inputs').onsubmit=e=>{e.preventDefault();state.moduleInputs=state.moduleInputs||{};state.moduleInputs[route]=Object.fromEntries(new FormData(e.target));log('Saved local input selection for '+route);toast('Input selection recorded locally. Backend validation pending.');};for(let k of ['vsh','phi','sw'])if($('#cut-'+k))$('#cut-'+k).oninput=e=>{state.cutoffs[k]=+e.target.value;save();render();$('#cut-'+k).focus();};if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();let f=e.target;state.settingsDraft=Object.fromEntries(new FormData(f));state.preferences={...state.preferences,...Object.fromEntries(new FormData(f))};for(let key of ['notifications','reviewAlerts','linkedDepth','autosave','gridDefault','reducedMotion'])state.preferences[key]=f.elements.namedItem(key)?.checked||false;state.project=f.elements.f0.value;let p=projectContext();if(p){p.name=state.project;p.updatedAt=new Date().toISOString();}state.projectNotes=f.elements.notes.value;if(state.preferences.mapDefault)state.basemap=state.preferences.mapDefault;log('Updated local project settings');toast('Project settings saved.');render();};if($('#depth-view'))$('#depth-view').onchange=e=>{if(e.target.value!=='MD / ft')toast('Depth conversion awaits a reviewed survey and datum. Chart remains MD.');};}
function action(a){if(a==='profile'){toggleProfile();return;}if(a==='help'){openHelp();return;}if(a==='projects'){navigate('projects');return;}fieldIndex=0;if(a==='workbench-annotation'){annotationEditor();return;}if(a==='workbench-reset-view'){state.workbenchUI=state.workbenchUI||{};state.workbenchUI[route]={};save();render();return;}if(a==='candidate-review'){candidateReview();return;}if(a==='menu'){$('.sidebar').classList.toggle('open');return;}if(a==='search'){searchModal();return;}if(a==='upload'){uploadModal();return;}if(a==='save-module'){saveModule();return;}if(a==='save-settings'){$('#settings-form').requestSubmit();return;}if(a==='export-workspace'){download('StrataX_workspace.json',JSON.stringify({schemaVersion:1,kind:'frontend-configuration',state},null,2));toast('Workspace exported.');return;}if(a==='export-catalog'){download('StrataX_feature_inventory.json',JSON.stringify(modules,null,2));return;}if(a==='export-files'){download('StrataX_source_inventory.json',JSON.stringify([...currentSampleFiles(),...state.files],null,2));return;}if(a==='export-summary'){download('StrataX_synthetic_summary.csv','dataset,well,zone,gross_ft,net_reservoir_ft,net_pay_ft\nSYNTHETIC EXAMPLE,'+state.well+',A,120,65,40\n','text/csv');return;}if(a==='print'){window.print();return;}if(a==='projects'){modal('Project workspace',`<p class="sub">Select a local project label. Demonstration evidence is shared in this frontend; production project isolation is not connected.</p><div style="margin-top:15px">${state.projects.map(p=>`<button class="search-result" data-project="${esc(p)}">${esc(p)}</button>`).join('')}</div><form id="new-project" style="margin-top:20px"><label class="field">New project name<input name="name" required maxlength="80"></label><button class="primary">Create local project</button></form>`);document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{state.project=b.dataset.project;save();$('#dialog').close();render();});$('#new-project').onsubmit=e=>{e.preventDefault();state.project=e.target.elements.namedItem('name').value;state.projects.push(state.project);save();$('#dialog').close();render();};return;}if(a==='notifications'&&!projectContext()?.demo){modal('Review notifications','<p class="sub">No pending review notifications in this project.</p>');return;}if(a==='notifications'){modal('Review notifications',`<div class="activity"><div>${icon('shield')}</div><div><h3>Survey references need confirmation</h3><p class="sub">TMB-04 and TMB-07 have unconfirmed azimuth references in the handover records.</p>${go('trajectories','Review configuration')}</div></div><div class="activity"><div>${icon('logs')}</div><div><h3>QC proposal awaits review</h3>${go('qc','Open QA/QC')}</div></div>`);return;}if(a==='crs'){modal('Coordinate reference review',`<div class="note amber">No georeferenced geometry is connected. Confirming these fields saves a draft only.</div><form id="crs-form" style="margin-top:20px">${field('Horizontal EPSG code','')}${field('Vertical datum','')}${field('Source documentation','')}<button class="primary">Save CRS draft</button></form>`);$('#crs-form').onsubmit=e=>{e.preventDefault();state.crsDraft=Object.fromEntries(new FormData(e.target));log('Saved CRS review draft');$('#dialog').close();toast('CRS draft saved. Geometry has not been transformed.');};return;}if(a==='add-layer'){modal('Add a project layer',`<form id="layer-form">${field('Layer type','GeoJSON|GeoTIFF|GeoPackage|Shapefile ZIP|WMS|WMTS|XYZ|Image')}${field('Layer name','')}${field('Source URL or file reference','')}<div class="note">Layer metadata is saved locally. Rendering external spatial data requires the relevant adapter.</div><button class="primary" style="margin-top:20px">Save layer specification</button></form>`);$('#layer-form').onsubmit=e=>{e.preventDefault();state.layerDrafts=state.layerDrafts||[];state.layerDrafts.push(Object.fromEntries(new FormData(e.target)));log('Added project layer specification');$('#dialog').close();toast('Layer specification saved; data adapter pending.');};return;}if(['zoom-in','zoom-out','fit'].includes(a)){state.mapZoom=a==='fit'?1:Math.max(.7,Math.min(2,state.mapZoom+(a==='zoom-in'?.15:-.15)));save();render();return;}if(a.startsWith('measure-')){state.measurement=a==='measure-clear'?null:a==='measure-area'?'Area':'Distance';state.measurePoints=[];save();render();if(state.measurement)toast('Click the map to sketch. Coordinates and ground distances are not calculated.');return;}if(a==='qc-accept'||a==='qc-reject'){state.qcDecision=a==='qc-accept'?'Accepted':'Rejected';state.downstreamStale=state.qcDecision==='Accepted';log(state.qcDecision+' local '+state.qcRecipe.toLowerCase()+' demonstration proposal');render();toast('Review decision saved locally.');return;}if(a==='save-cutoffs'){state.cutoffNote=$('#cutoff-note')?.value||'';log('Saved cutoff draft');toast('Cutoff version saved locally.');return;}if(a==='duplicate'){modal('Duplicate scenario',`<form id="duplicate-form">${field('Scenario name',state.scenario+' copy')}<button class="primary">Save scenario label</button></form>`);$('#duplicate-form').onsubmit=e=>{e.preventDefault();state.scenario=e.target.elements.f0.value;log('Created scenario label '+state.scenario);$('#dialog').close();toast('Scenario label saved.');};return;}if(a==='view-config'){modal('Saved configuration',`<pre style="white-space:pre-wrap;font-size:11px">${esc(JSON.stringify(state.configs[route]||{status:'Not configured'},null,2))}</pre>`);return;}if(a==='report-sections'){let sections=['Evidence inventory','QA/QC decisions','Interpretation methods','Reservoir summaries','Limitations & provenance'];modal('Report sections',`<form id="sections-form"><div class="toggle-list">${sections.map(s=>`<label>${s}<input name="section" value="${s}" type="checkbox" ${(state.reportSections||sections).includes(s)?'checked':''}></label>`).join('')}</div><button class="primary" style="margin-top:20px">Apply sections</button></form>`);$('#sections-form').onsubmit=e=>{e.preventDefault();state.reportSections=new FormData(e.target).getAll('section');save();$('#dialog').close();render();};return;}if(a==='reset'){modal('Reset local demonstration',`<p>This clears configurations and local review decisions in this browser. Original uploaded files are not affected.</p><button id="confirm-reset" class="primary">Reset local workspace</button>`);$('#confirm-reset').onclick=()=>{state=structuredClone(initial);state.project=projectContext()?.name||'Untitled';if(!projectContext()?.demo){state.files=[];state.well='';}save();$('#dialog').close();navigate('overview');};return;}if(a==='save-layout'){modal('Save log layout',`<form id="layout-form">${field('Layout name','My interpretation layout')}<button class="primary">Save layout</button></form>`);$('#layout-form').onsubmit=e=>{e.preventDefault();state.savedLayouts.push({name:e.target.elements.f0.value,well:state.well});log('Saved log display layout');$('#dialog').close();toast('Layout saved locally.');};return;}if(a==='permissions'){modal('Permission matrix',`<table><tr><th>Action</th><th>Owner</th><th>Interpreter</th><th>Reviewer</th><th>Viewer</th></tr>${[['Manage project','Yes','No','No','No'],['Edit drafts','Yes','Yes','No','No'],['Approve results','Yes','No','Yes','No'],['View accepted results','Yes','Yes','Yes','Yes']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</table><p class="note">Proposed permissions. Backend enforcement is required.</p>`);return;}if(a==='definitions'){modal('Summary definitions',`<p><strong>Gross thickness:</strong> selected zone interval on the declared depth basis.</p><p><strong>Evaluated thickness:</strong> interval with eligible inputs.</p><p><strong>Net reservoir:</strong> interval passing reservoir criteria.</p><p><strong>Net pay:</strong> interval passing reservoir and hydrocarbon criteria.</p><p><strong>NTG:</strong> net reservoir divided by the declared gross denominator.</p><div class="note">MD thickness is not automatically vertical or true stratigraphic thickness.</div>`);return;}if(a==='add-well'){modal('Register a well',`<form id="well-form">${field('Well ID','')}${field('Well aliases','')}${field('Source evidence reference','')}<button class="primary">Save well registration draft</button></form>`);$('#well-form').onsubmit=e=>{e.preventDefault();state.wellDrafts=state.wellDrafts||[];state.wellDrafts.push(Object.fromEntries(new FormData(e.target)));log('Saved well registration draft');$('#dialog').close();toast('Well draft saved. Source validation awaits backend integration.');};return;}if(['display','add-track','markers','compare-wells','compare-scenarios'].includes(a)){let title={display:'Display settings','add-track':'Add track',markers:'Formation markers','compare-wells':'Compare wells','compare-scenarios':'Compare scenarios'}[a];modal(title,`<form id="view-form"><div class="form-grid">${a==='markers'?field('Marker name','Zone A')+field('Pick depth (ft MD)','4350'):a==='compare-wells'?wells.map(w=>`<label class="layer"><input type="checkbox" name="well" value="${w.id}" ${w.id===state.well?'checked':''}>${w.id}</label>`).join(''):field('Name / template','Custom')+field('Scale','Linear|Logarithmic')+field('Minimum','0')+field('Maximum','150')}</div><div class="note">This saves a frontend display specification. Connected curve rendering will use this configuration.</div><button class="primary" style="margin-top:15px">Save specification</button></form>`);$('#view-form').onsubmit=e=>{e.preventDefault();state.viewSpecs=state.viewSpecs||[];state.viewSpecs.push({kind:a,fields:[...new FormData(e.target).entries()]});log('Saved '+title.toLowerCase()+' specification');$('#dialog').close();toast('Display specification saved.');};return;}if(a==='help'){modal('Working in StrataX',`<p>Start in Data to review sources, use Map for spatial context, then move through the six interpretation stages.</p><div class="status-row"><span>Search tools and wells</span><strong>Ctrl / ⌘ K</strong></div><div class="status-row"><span>Close a panel</span><strong>Escape</strong></div><p class="note">This is a frontend foundation. Data is synthetic, files stay local, and calculation services are not connected. The feature inventory distinguishes interactive workspaces from configuration scaffolds.</p>${go('catalog','Open feature inventory')}`);}}
function searchModal(){modal('Search workspace',`<input id="global-search" placeholder="Try saturation, TMB-04, maps…" aria-label="Search workspace" style="width:100%"><div id="search-results" style="margin-top:15px;max-height:380px;overflow:auto"></div>`);let populate=q=>{$('#search-results').innerHTML=[...modules.filter(m=>(m.name+' '+m.features.join(' ')).toLowerCase().includes(q.toLowerCase())).map(m=>({label:m.name,sub:m.group,id:m.id})),...wells.filter(w=>w.id.toLowerCase().includes(q.toLowerCase())).map(w=>({label:w.id,sub:'Well · Open log viewer',id:'logs',well:w.id}))].slice(0,12).map(r=>`<button class="search-result" data-result="${r.id}" ${r.well?`data-resultwell="${r.well}"`:''}>${esc(r.label)}<small>${esc(r.sub)}</small></button>`).join('')||'<p class="sub">No matching workspace items.</p>';document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{if(b.dataset.resultwell)state.well=b.dataset.resultwell;$('#dialog').close();navigate(b.dataset.result);});};populate('');$('#global-search').oninput=e=>populate(e.target.value);$('#global-search').focus();}
function uploadModal(){fieldIndex=0;modal('Import source files',`<form id="upload-form"><div class="form-grid">${field('Evidence category','Well logs|Deviation|Well headers|Well tops|Core data|Reports|Drilling logs|Geochemistry|Maps')}${field('Associate with well','Unassigned|'+wells.map(w=>w.id).join('|'))}</div><div class="upload-zone">${icon('upload')}<h3>Select your source files</h3><p>LAS, DLIS, LIS, tabular files, surveys, maps and supporting documents</p><input id="file-input" type="file" multiple required aria-label="Choose source files"><p>Local metadata only. No files are sent to a server.</p></div><p id="file-list" class="sub" style="margin:12px 0"></p><button class="primary" type="submit">Add to local review queue</button></form>`);$('#file-input').onchange=e=>{$('#file-list').textContent=Array.from(e.target.files).map(f=>f.name).join(', ');};$('#upload-form').onsubmit=e=>{e.preventDefault();let form=e.target;for(let f of $('#file-input').files){state.files.push({name:f.name,type:form.elements.f0.value,well:form.elements.f1.value,status:'Metadata only',size:(f.size/1024).toFixed(1)+' KB',local:true});}log('Added local file metadata to review queue');$('#dialog').close();navigate('files');toast('File metadata added. Parsing and upload services are not connected.');};}
function fileReview(name){fieldIndex=0;let f=[...currentSampleFiles(),...state.files].find(f=>f.name===name);modal('Review source mapping',`<p class="well-name">${esc(name)}</p><div class="note">${f.local?'This is local metadata. File contents have not been parsed.':'Demonstration source record. No original file is connected.'}</div><form id="file-review" style="margin-top:20px"><div class="form-grid">${field('Evidence category',[f.type,...['Well logs','Deviation','Well headers','Well tops','Core data','Reports'].filter(x=>x!==f.type)].join('|'))}${field('Well association',[f.well,...wells.map(w=>w.id).filter(w=>w!==f.well)].join('|'))}${field('Depth column','Not parsed')}${field('Depth units','Unconfirmed|Feet|Metres')}${field('Null sentinel','-9999')}${field('Mapping decision','Draft|Retained as evidence')}</div><button class="primary">Save mapping draft</button></form>`);$('#file-review').onsubmit=e=>{e.preventDefault();if(f.local){f.type=e.target.elements.f0.value;f.well=e.target.elements.f1.value;}state.mappingDrafts=state.mappingDrafts||{};state.mappingDrafts[name]=Object.fromEntries(new FormData(e.target));log('Saved mapping draft for '+name);$('#dialog').close();render();toast('Mapping draft saved. Source eligibility is unchanged.');};}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();if(!$('#dialog').open)searchModal();}});window.addEventListener('hashchange',()=>{let next=location.hash.slice(1)||'home';if(next!==route){route=next;render();}});render();
function featureEditor(feature){let key=route+':'+feature;let spec=state.featureSpecs?.[key]||{};modal(feature,`<p class="sub">${esc(modules.find(m=>m.id===route)?.name)} / Feature specification</p><form id="feature-form" style="margin-top:20px"><div class="form-grid"><label class="field">Scope<select name="scope"><option>Selected well and interval</option><option>Selected wells</option><option>Project</option></select></label><label class="field">Review requirement<select name="review"><option>Reviewer acceptance required</option><option>Draft / comparison only</option></select></label><label class="field">Input version / source<input name="input" value="${esc(spec.input||'')}" placeholder="Awaiting connected evidence"></label><label class="field">Parameter expression / configuration<input name="parameters" value="${esc(spec.parameters||'')}" placeholder="Define values and units"></label></div><label class="field">Requirements and acceptance notes<textarea name="notes">${esc(spec.notes||'')}</textarea></label><div class="note">Saving records the interface specification. It does not execute the feature or establish evidence eligibility.</div><button class="primary" style="margin-top:16px">Save feature specification</button></form>`);$('#feature-form').onsubmit=e=>{e.preventDefault();state.featureSpecs=state.featureSpecs||{};state.featureSpecs[key]=Object.fromEntries(new FormData(e.target));log('Configured '+feature);$('#dialog').close();toast('Feature specification saved locally.');};}
function bindWorkbench(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.workbenchUI=state.workbenchUI||{};state.workbenchUI[route]={...state.workbenchUI[route],view:b.dataset.view};save();render();});let ws=$('#workbench-well');if(ws)ws.onchange=e=>{state.well=e.target.value;save();render();};for(let [id,k] of [['show-overlay','overlay'],['link-depth','linkDepth']])if($('#'+id))$('#'+id).onchange=e=>{state.workbenchUI=state.workbenchUI||{};state.workbenchUI[route]={...state.workbenchUI[route],[k]:e.target.checked};save();if(k==='overlay')$('.visual-canvas')?.classList.toggle('overlay-off',!e.target.checked);};document.querySelectorAll('[data-sample]').forEach(b=>{b.onclick=()=>modal('Synthetic sample '+b.dataset.sample,`<div class="note">Illustrative point for interaction review. There is no field measurement associated with this point.</div><div class="status-row"><span>Sample reference</span><strong>EX-${b.dataset.sample}</strong></div><div class="status-row"><span>Well context</span><strong>${state.well}</strong></div>`);b.onkeydown=e=>{if(e.key==='Enter')b.click();};});}
function annotationEditor(){modal('Add review annotation',`<form id="annotation-form"><label class="field">Annotation<textarea name="text" required placeholder="Record your observation…"></textarea></label><label class="field">Depth, sample or view reference<input name="reference" placeholder="For example: EX-25, Zone A"></label><button class="primary">Save annotation</button></form>`);$('#annotation-form').onsubmit=e=>{e.preventDefault();state.annotations=state.annotations||{};state.annotations[route]=state.annotations[route]||[];state.annotations[route].push(Object.fromEntries(new FormData(e.target)));log('Added '+route+' review annotation');$('#dialog').close();render();};}
function candidateReview(){modal('Candidate EX-001 review',`<div class="note amber">Synthetic example. An interval cannot be confirmed as overlooked pay without the relevant completion and production evidence.</div><form id="candidate-form" style="margin-top:20px"><label class="field">Decision<select name="decision"><option>Needs more evidence</option><option>Retain for review</option><option>Reject candidate</option></select></label><label class="field">Rationale<textarea name="rationale" required></textarea></label><button class="primary">Record local review</button></form>`);$('#candidate-form').onsubmit=e=>{e.preventDefault();state.candidateDecision=e.target.elements.decision.value;log('Candidate EX-001: '+state.candidateDecision);$('#dialog').close();render();};}
function renderProjects(){let records=portfolio.records.filter(p=>projectFilter==='Trash'?p.status==='Trash':projectFilter==='Archived'?p.status==='Archived':projectFilter==='Favorites'?p.favorite&&p.status!=='Trash':projectFilter==='All'?p.status!=='Trash':p.status==='Active').filter(p=>(p.name+' '+p.description+' '+p.location).toLowerCase().includes(projectQuery.toLowerCase()));records.sort((a,b)=>projectSort==='name'?a.name.localeCompare(b.name):projectSort==='created'?b.createdAt.localeCompare(a.createdAt):b.updatedAt.localeCompare(a.updatedAt));let active=portfolio.records.filter(p=>p.status==='Active').length;$('#app').innerHTML=`<div class="portfolio-shell"><header class="portfolio-header"><div class="brand"><img src="logo.png" alt="StrataX logo"><div>StrataX<small>Subsurface workspace</small></div></div><div class="actions"><span class="demo-pill">FRONTEND PREVIEW</span>${profileMenu()}</div></header><main class="portfolio-main">${heading('Projects','Organize your studies. Open a project to work with its data and interpretations.',btn(icon('plus')+'New project','new-project',true),'YOUR WORKSPACE')}${projectInsights()}<div class="portfolio-summary"><span><strong>${active}</strong> active ${active===1?'project':'projects'}</span><span><strong>${portfolio.records.filter(p=>p.favorite&&p.status!=='Trash').length}</strong> favorites</span><span><strong>${portfolio.records.filter(p=>p.status==='Archived').length}</strong> archived</span></div><div class="portfolio-tools"><div class="pill-group">${['Active','All','Favorites','Archived','Trash'].map(t=>`<button data-projectfilter="${t}" class="${projectFilter===t?'active':''}">${t}</button>`).join('')}</div><div class="actions"><label class="project-search">${icon('search')}<input id="project-search" aria-label="Search projects" placeholder="Search projects…" value="${esc(projectQuery)}"></label><select id="project-sort" aria-label="Sort projects"><option value="recent" ${projectSort==='recent'?'selected':''}>Recently updated</option><option value="name" ${projectSort==='name'?'selected':''}>Name A–Z</option><option value="created" ${projectSort==='created'?'selected':''}>Newest first</option></select><button data-projectview="${projectView==='grid'?'list':'grid'}" aria-label="Switch to ${projectView==='grid'?'list':'grid'} view">${icon(projectView==='grid'?'data':'overview')}</button></div></div>${records.length?(projectView==='grid'?`<div class="project-grid">${records.map(projectCard).join('')}</div>`:`<div class="panel table-wrap"><table><thead><tr><th>Project</th><th>Location</th><th>Type</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody>${records.map(p=>`<tr><td><button class="quiet" data-openproject="${p.id}">${esc(p.name)}</button></td><td>${esc(p.location||'Not specified')}</td><td>${esc(p.type)}</td><td>${badge(p.status,p.status==='Active'?'green':'gray')}</td><td>${new Date(p.updatedAt).toLocaleDateString()}</td><td>${projectActions(p)}</td></tr>`).join('')}</tbody></table></div>`):`<div class="portfolio-empty">${icon('layers')}<h2>${projectQuery?'No matching projects':projectFilter==='Active'?'Your next study starts here':'No '+projectFilter.toLowerCase()+' projects'}</h2><p class="sub">${projectQuery?'Try another project name or location.':'Create a project to organize sources, maps and interpretation work.'}</p><div style="margin-top:20px">${btn('New project','new-project',true)}</div></div>`}<footer class="portfolio-footer"><span>StrataX · Evidence-led subsurface interpretation</span><span>Projects and changes are stored in this browser in this frontend preview.</span></footer></main></div>`;document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(b.dataset.action==='new-project')projectEditor();else action(b.dataset.action);});document.querySelectorAll('[data-progress]').forEach(b=>b.onclick=()=>progressEditor(b.dataset.progress));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-projectfilter]').forEach(b=>b.onclick=()=>{projectFilter=b.dataset.projectfilter;renderProjects();});document.querySelectorAll('[data-projectview]').forEach(b=>b.onclick=()=>{projectView=b.dataset.projectview;renderProjects();});document.querySelectorAll('[data-openproject]').forEach(b=>b.onclick=()=>openProject(b.dataset.openproject));document.querySelectorAll('[data-projectmenu]').forEach(b=>b.onclick=()=>projectMenu(b.dataset.projectmenu));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{let p=portfolio.records.find(p=>p.id===b.dataset.favorite);p.favorite=!p.favorite;persistPortfolio();renderProjects();});$('#project-search').oninput=e=>{projectQuery=e.target.value;let pos=e.target.selectionStart;renderProjects();$('#project-search').focus();$('#project-search').setSelectionRange(pos,pos);};$('#project-sort').onchange=e=>{projectSort=e.target.value;renderProjects();};}
function projectActions(p){return `<div class="actions">${p.status!=='Trash'?`<button data-openproject="${p.id}">Open project ${icon('arrow')}</button>`:''}<button data-projectmenu="${p.id}" aria-label="Manage ${esc(p.name)}">${icon('settings')}</button></div>`;}
function projectCard(p){let ctx=portfolio.contexts[p.id],fileCount=(ctx?.files||[]).length;return `<article class="project-card"><div class="project-card-top"><span class="project-emblem">${icon(p.demo?'map':'layers')}</span><div class="actions"><button class="favorite ${p.favorite?'is-favorite':''}" data-favorite="${p.id}" aria-label="${p.favorite?'Unfavorite':'Favorite'} ${esc(p.name)}" aria-pressed="${!!p.favorite}">${p.favorite?'★':'☆'}</button><button class="quiet icon" data-projectmenu="${p.id}" aria-label="Manage ${esc(p.name)}">${icon('settings')}</button></div></div><div class="project-card-title"><h2>${esc(p.name)}</h2>${p.demo?badge('Demo','gray'):badge(p.status,p.status==='Active'?'green':'gray')}</div><p class="project-description">${esc(p.description||'No description added yet.')}</p><div class="project-location">${icon('pin')}${esc(p.location||'Location not specified')}</div>${projectCardProgress(p)}<div class="project-card-meta"><span>${esc(p.type)}</span><span>${p.demo?'6 demo wells':fileCount+' source files'}</span></div><div class="project-card-bottom"><span>Updated ${new Date(p.updatedAt).toLocaleDateString()}</span>${p.status!=='Trash'?`<button data-openproject="${p.id}">Open project ${icon('arrow')}</button>`:`<button data-projectmenu="${p.id}">Restore project</button>`}</div></article>`;}
function projectEditor(id){let p=portfolio.records.find(p=>p.id===id);modal(p?'Edit project':'Create a project',`<form id="project-editor"><label class="field">Project name<input name="name" value="${esc(p?.name||'')}" placeholder="For example: Obodo reservoir evaluation" required maxlength="100"></label><div class="form-grid"><label class="field">Project type<select name="type">${['Petrophysical evaluation','Legacy data recovery','Field development','Research study','Integrated subsurface study'].map(t=>`<option ${p?.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Location / field<input name="location" value="${esc(p?.location||'')}" placeholder="Field, basin or region" maxlength="150"></label></div><label class="field">Description<textarea name="description" maxlength="1000" placeholder="What will this project investigate?">${esc(p?.description||'')}</textarea></label>${!p?'<label class="layer"><input name="open" type="checkbox" checked>Open project after creating</label>':''}<div class="actions" style="margin-top:18px"><button type="submit" class="primary">${p?'Save project':'Create project'}</button><button type="button" id="project-cancel">Cancel</button></div></form>`);$('#project-cancel').onclick=()=>$('#dialog').close();$('#project-editor').onsubmit=ev=>{ev.preventDefault();let f=new FormData(ev.target),name=String(f.get('name')).trim();if(!name){ev.target.elements.namedItem('name').setCustomValidity('Enter a project name.');ev.target.reportValidity();return;}let duplicate=portfolio.records.some(r=>r.id!==id&&r.status!=='Trash'&&r.name.toLowerCase()===name.toLowerCase());if(duplicate){toast('A project with this name already exists. Choose a different name.');return;}let now=new Date().toISOString();if(p){Object.assign(p,{name,type:f.get('type'),location:f.get('location'),description:f.get('description'),updatedAt:now});if(p.id===portfolio.activeId)state.project=name;if(portfolio.contexts[p.id])portfolio.contexts[p.id].project=name;}else{p={id:localProjectId(),name,type:f.get('type'),location:f.get('location'),description:f.get('description'),status:'Active',favorite:false,demo:false,createdAt:now,updatedAt:now};portfolio.records.push(p);portfolio.contexts[p.id]=freshProjectContext(name);}persistPortfolio();$('#dialog').close();if(f.get('open'))openProject(p.id);else{renderProjects();toast(id?'Project updated.':'Project created.');}};}
function freshProjectContext(name){return {...structuredClone(initial),project:name,well:'',files:[],audit:[],configs:{},savedLayouts:[],projects:[],layers:{wells:true,paths:false,boundary:false,faults:false,grid:false}};}
function openProject(id){let p=portfolio.records.find(p=>p.id===id);if(!p||p.status==='Trash')return;portfolio.contexts[portfolio.activeId]=structuredClone(state);portfolio.activeId=id;state=structuredClone(portfolio.contexts[id]||freshProjectContext(p.name));state.project=p.name;wells=p.demo?demoWells:[];p.lastOpenedAt=new Date().toISOString();save();navigate('overview');}
function projectMenu(id){let p=portfolio.records.find(p=>p.id===id);if(!p)return;modal('Manage '+esc(p.name),`<div class="project-menu"><button id="project-edit">${icon('file')}Edit project details</button><button id="project-duplicate">${icon('layers')}Duplicate project</button><button id="project-archive">${icon('clock')}${p.status==='Archived'?'Restore to active projects':'Archive project'}</button>${p.status==='Trash'?'<button id="project-restore">Restore from trash</button>':'<button id="project-trash" class="danger">Move to trash</button>'}</div><p class="note" style="margin-top:18px">Archived projects remain available. Projects in Trash can be restored. No server data is modified in this frontend preview.</p>`);$('#project-edit').onclick=()=>{$('#dialog').close();projectEditor(id);};$('#project-duplicate').onclick=()=>{let copy=structuredClone(p);copy.id=localProjectId();copy.name=p.name+' copy';let n=2;while(portfolio.records.some(r=>r.name===copy.name))copy.name=p.name+' copy '+n++;copy.favorite=false;copy.status='Active';copy.createdAt=copy.updatedAt=new Date().toISOString();portfolio.records.push(copy);portfolio.contexts[copy.id]=structuredClone(id===portfolio.activeId?state:portfolio.contexts[id]||freshProjectContext(copy.name));portfolio.contexts[copy.id].project=copy.name;persistPortfolio();$('#dialog').close();projectFilter='Active';renderProjects();toast('Project duplicated with an independent local workspace.');};$('#project-archive').onclick=()=>{p.status=p.status==='Archived'?'Active':'Archived';p.updatedAt=new Date().toISOString();persistPortfolio();$('#dialog').close();renderProjects();toast(p.status==='Archived'?'Project archived.':'Project restored.');};if($('#project-trash'))$('#project-trash').onclick=()=>{modal('Move project to trash?',`<p><strong>${esc(p.name)}</strong> will be removed from your project lists. Its local workspace can be restored from Trash.</p><div class="actions" style="margin-top:20px"><button id="confirm-project-trash" class="danger">Move to trash</button><button id="cancel-project-trash">Cancel</button></div>`);$('#cancel-project-trash').onclick=()=>$('#dialog').close();$('#confirm-project-trash').onclick=()=>{p.previousStatus=p.status;p.status='Trash';p.updatedAt=new Date().toISOString();persistPortfolio();$('#dialog').close();renderProjects();toast('Project moved to Trash. You can restore it.');};};if($('#project-restore'))$('#project-restore').onclick=()=>{p.status=p.previousStatus||'Active';p.updatedAt=new Date().toISOString();persistPortfolio();$('#dialog').close();renderProjects();toast('Project restored.');};}
function publicHeader(){return `<header class="public-header"><a class="brand" href="#home" aria-label="StrataX home"><img src="logo.png" alt="StrataX logo"><span>StrataX</span></a><nav aria-label="Website navigation"><a href="#home" data-section="platform">Platform</a><a href="#home" data-section="workflow">Workflow</a><a href="#home" data-section="evidence">Why StrataX</a></nav><div class="actions"><a class="public-signin" href="#signin">Sign in</a><a class="button-link primary" href="#signup">Get started ${icon('arrow')}</a></div></header>`;}
function renderPublicPage(){if(route==='home'){renderLanding();return;}let signup=route==='signup',forgot=route==='forgot-password';$('#app').innerHTML=`<div class="auth-shell"><section class="auth-story"><a class="brand" href="#home"><img src="logo.png" alt="StrataX logo"><span>StrataX</span></a><div class="auth-story-content"><div class="eyebrow">FROM EVIDENCE TO UNDERSTANDING</div><h1>A clearer view<br>of the subsurface.</h1><p>Bring your well data, interpretation and project decisions into one organized workspace.</p><div class="auth-visual">${chart()}</div><div class="auth-proof">${icon('shield')}Source-linked interpretation. Review at every step.</div></div><span class="auth-story-footer">TerraCode Analytics · StrataX</span></section><section class="auth-panel"><a class="back-home" href="#home">← Back to home</a><div class="auth-form-wrap"><div class="eyebrow">${forgot?'ACCOUNT RECOVERY':signup?'CREATE YOUR WORKSPACE':'WELCOME BACK'}</div><h1>${forgot?'Reset your password':signup?'Create your account':'Sign in to StrataX'}</h1><p class="sub">${forgot?'Enter the email associated with your account.':signup?'Start with a project. Build understanding from your evidence.':'Continue to your projects and interpretation workspace.'}</p><div class="auth-preview-notice">Frontend preview. Account creation, login and email delivery are not connected. Do not enter a real password.</div>${!forgot?'<button class="google-button" id="google-auth"><span class="google-letter">G</span>Continue with Google</button><div class="auth-divider"><span>or continue with email</span></div>':''}<form id="auth-form">${signup?'<label class="field">Full name<input name="fullName" autocomplete="name" required placeholder="Your full name" maxlength="100"></label><label class="field">Organization <span class="optional">optional</span><input name="organization" autocomplete="organization" placeholder="Company or institution" maxlength="150"></label>':''}<label class="field">Work email<input type="email" name="email" autocomplete="email" required placeholder="you@company.com"></label>${!forgot?`<label class="field">${signup?'Create a demo password':'Demo password'}<div class="password-field"><input type="password" id="auth-password" name="password" autocomplete="off" required minlength="${signup?8:1}" placeholder="${signup?'At least 8 characters':'Use a sample password'}"><button type="button" id="toggle-password" aria-label="Show password">${icon('eye')}</button></div></label>${signup?'<p class="password-hint">Use a sample value with at least 8 characters. It will not be stored or sent.</p>':'<div class="auth-options"><label><input name="remember" type="checkbox">Remember this device</label><a href="#forgot-password">Forgot password?</a></div>'}`:''}<div id="auth-feedback" role="status"></div><button class="primary auth-submit" type="submit">${forgot?'Preview reset request':signup?'Preview account setup':'Preview sign in'} ${icon('arrow')}</button></form><p class="auth-alternative">${forgot?'<a href="#signin">Return to sign in</a>':signup?'Already have an account? <a href="#signin">Sign in</a>':'New to StrataX? <a href="#signup">Create an account</a>'}</p><div class="auth-preview-entry"><span>Explore the interface without an account</span><button id="enter-demo">Open preview workspace ${icon('arrow')}</button></div><p class="auth-privacy">The preview does not create an account or accept legal terms. Authentication and account policies will be added before release.</p></div><div class="auth-panel-footer">© ${new Date().getFullYear()} TerraCode Analytics</div></section></div>`;if($('#toggle-password'))$('#toggle-password').onclick=()=>{let p=$('#auth-password');p.type=p.type==='password'?'text':'password';$('#toggle-password').setAttribute('aria-label',p.type==='password'?'Show password':'Hide password');};if($('#google-auth'))$('#google-auth').onclick=()=>{modal('Google sign-in integration',`<p class="sub">Google authentication is not connected in this frontend preview. No account information has been requested.</p><div style="margin-top:20px">${go('projects','Explore the preview workspace',true)}</div>`);};$('#enter-demo').onclick=()=>navigate('projects');$('#auth-form').onsubmit=ev=>{ev.preventDefault();let form=ev.target;if(!form.reportValidity())return;let pwd=form.elements.namedItem('password');if(pwd)pwd.value='';$('#auth-feedback').innerHTML=`<div class="note ${forgot?'':'amber'}" style="margin-bottom:16px">${forgot?'The email field passed validation. No reset email was sent because account recovery is not connected.':'The form passed validation. No account was created or authenticated. Use the preview workspace below to explore the frontend.'}</div>`;};}
function renderLanding(){$('#app').innerHTML=`<div class="landing">${publicHeader()}<main><section class="landing-hero"><div class="hero-copy"><span class="hero-category"><span class="dot"></span>SUBSURFACE INTERPRETATION WORKSPACE</span><h1>Know your data.<br>See what’s possible.</h1><p>A focused workspace for well data, petrophysical interpretation and evidence-led decisions. From your first legacy file to a reviewed reservoir study.</p><div class="hero-actions"><a class="button-link primary" href="#signup">Start a project ${icon('arrow')}</a><a class="button-link" href="#projects">Explore the preview ${icon('eye')}</a></div><span class="hero-footnote">Frontend preview · Demonstration data · No account required to explore</span><div class="hero-topics"><span>Well data & documents</span><span>Petrophysics</span><span>Spatial context</span></div></div><div class="hero-product"><div class="product-window-bar"><span class="window-dots">● ● ●</span><span>StrataX / Tomboy field / Interpretation</span><span class="badge green">Demo workspace</span></div><div class="hero-product-layout"><div class="hero-mini-nav"><img src="logo.png" alt=""><span class="mini-item">Overview</span><span class="mini-item">Data</span><span class="mini-item">Map</span><span class="mini-item selected">Interpretation</span><span class="mini-item">Reports</span></div><div class="hero-mini-workspace"><div class="hero-mini-heading"><div><small>WELL LOG WORKSPACE</small><h3>Evidence, in context.</h3></div><span class="badge gray">TMB-02</span></div><div class="hero-log-labels"><span>DEPTH</span><span>GAMMA RAY</span><span>RESISTIVITY</span><span>DENSITY</span><span>NEUTRON</span></div>${chart()}<div class="hero-mini-status"><span><i class="dot"></i>Original measurements preserved</span><span>Illustrative log tracks</span></div></div></div><div class="hero-floating-card">${icon('shield')}<span><strong>Every decision has a source.</strong><small>Review the evidence behind your interpretation.</small></span></div></div></section><section class="landing-section platform-section" id="platform"><div class="section-heading"><div class="eyebrow">ONE CONNECTED WORKSPACE</div><h2>Less time finding files.<br>More time understanding them.</h2><p>Keep your project context close as you move between data, maps and interpretation.</p></div><div class="landing-features">${[['data','Bring order to your evidence','Organize well logs, drilling records, reports, geochemistry and maps around the wells they describe.'],['map','Keep the field in view','Review well positions, deviation paths and project layers alongside coordinate references.'],['logs','Work through interpretation','Move from QC and lithology to calibrated properties, cutoff criteria and reservoir summaries.'],['reports','Make review part of the work','Compare versions, record assumptions and carry source references into your deliverables.']].map(([i,t,d])=>`<article><div class="landing-feature-icon">${icon(i)}</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="workflow-section" id="workflow"><div class="section-heading"><div class="eyebrow">A FAMILIAR SCIENTIFIC WORKFLOW</div><h2>Clear steps.<br>Room for expert judgment.</h2><p>Follow the full petrophysical workflow with detailed tools available in context.</p></div><div class="landing-workflow">${stages.map(([id,t,d],i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section><section class="landing-section evidence-section" id="evidence"><div><div class="eyebrow">BUILT AROUND EVIDENCE</div><h2>Keep the original.<br>Understand every change.</h2><p>StrataX is being built around traceable sources, explicit assumptions and reviewed interpretation. Its scientific capabilities remain subject to implementation and validation.</p><a class="button-link" href="#catalog">Explore the feature inventory ${icon('arrow')}</a></div><div class="evidence-stack">${[['01','Source evidence','Retain original files and their identity.'],['02','Reviewed interpretation','Distinguish measured, conditioned and reconstructed information.'],['03','Traceable decisions','Record methods, parameters and reviewer decisions.']].map(([n,t,d])=>`<article><span>${n}</span><div><h3>${t}</h3><p>${d}</p></div>${icon('check')}</article>`).join('')}</div></section><section class="landing-cta"><div><h2>Your next study starts with a project.</h2><p>Explore how the complete StrataX workspace fits together.</p></div><a class="button-link" href="#projects">Open the frontend preview ${icon('arrow')}</a></section></main><footer class="landing-footer"><a class="brand" href="#home"><img src="logo.png" alt=""><span>StrataX</span></a><span>© ${new Date().getFullYear()} TerraCode Analytics</span><div><a href="#signin">Sign in</a><a href="#signup">Create account</a><button class="quiet" id="about-preview">About this preview</button></div></footer></div>`;document.querySelectorAll('[data-section]').forEach(a=>a.onclick=ev=>{ev.preventDefault();$('#'+a.dataset.section)?.scrollIntoView({behavior:'smooth'});});$('#about-preview').onclick=()=>modal('About the frontend preview',`<p>This is a design and interaction foundation for StrataX. Records and visuals are illustrative. Projects, configuration drafts and review decisions are stored in this browser.</p><p>No authentication, scientific calculation, server upload or email service is connected.</p>${go('projects','Open Projects',true)}`);}
function newProjectOverview(){let p=projectContext();return heading(esc(state.project),'Build your evidence catalogue, then work through the interpretation workflow.',btn(icon('upload')+'Import data','upload',true),'PROJECT OVERVIEW')+`<div class="stats">${[['Wells',0],['Source files',state.files.length],['Saved configurations',Object.keys(state.configs).length],['Local decisions',state.audit.length]].map(([t,n])=>`<div class="stat"><div class="stat-top">${t}</div><div class="stat-value">${n}</div><small>This project only</small></div>`).join('')}</div><div class="grid">${panel('Start with your evidence',`<div class="panel-body"><h2 style="margin-bottom:12px">Your project is ready.</h2><p class="sub">Add your source files and associate them with wells before interpretation. New projects do not inherit demonstration data.</p><div class="actions" style="margin-top:22px">${btn('Import source files','upload',true)}${go('files','View source inventory')}</div><div class="note" style="margin-top:22px">Local file metadata and drafts are separated by project. Scientific parsing and server storage will connect later.</div></div>`)}${panel('Project details',`<div class="panel-body"><div class="status-row"><span>Type</span><strong>${esc(p?.type||'Study')}</strong></div><div class="status-row"><span>Location</span><span>${esc(p?.location||'Not specified')}</span></div><p class="sub" style="margin-top:15px">${esc(p?.description||'No description added.')}</p><div style="margin-top:18px">${go('projects','Back to all projects')}</div></div>`)}</div>`;}

function localProjectId(){return typeof crypto.randomUUID==='function'?crypto.randomUUID():'project-'+Date.now().toString(36)+'-'+Array.from(crypto.getRandomValues(new Uint8Array(8)),v=>v.toString(16).padStart(2,'0')).join('');}
function profileName(){return state.preferences?.displayName||'TerraCode Analytics';}
function profileInitials(){return profileName().trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();}
function profileMenu(){return `<div class="profile-anchor"><div class="profile-popover" id="profile-popover" hidden><div class="profile-popover-head"><strong>${esc(profileName())}</strong><small>${esc(state.preferences?.jobTitle||'Project owner')} · Local workspace</small></div><button data-go="catalog">${icon('layers')}Feature inventory</button><button data-go="settings">${icon('settings')}Settings & preferences</button><button data-action="help">${icon('help')}Help & keyboard shortcuts</button><div class="profile-menu-divider"></div><button data-go="projects">${icon('overview')}All projects</button><button data-go="home">${icon('arrow')}Exit preview</button></div><button class="profile-trigger" data-action="profile" aria-haspopup="true" aria-expanded="false" aria-controls="profile-popover"><span class="profile-avatar">${profileInitials()}<i></i></span><span class="profile-text"><strong>${esc(profileName())}</strong><small>${esc(state.preferences?.jobTitle||'Project owner')}</small></span>${icon('down')}</button></div>`;}
function toggleProfile(){let p=$('#profile-popover'),t=$('[data-action=profile]');if(!p)return;p.hidden=!p.hidden;t.setAttribute('aria-expanded',String(!p.hidden));}
document.addEventListener('click',e=>{if(!e.target.closest('.profile-anchor')){let p=$('#profile-popover');if(p){p.hidden=true;$('[data-action=profile]')?.setAttribute('aria-expanded','false');}}});
function applyPreferences(){let p=state.preferences||{};document.documentElement.dataset.density=p.density||'Comfortable';document.documentElement.dataset.textsize=p.fontSize||'Standard';document.documentElement.dataset.accent=p.accent||'Teal';document.documentElement.dataset.curveweight=p.curveThickness||'Standard';document.documentElement.dataset.loggrid=p.gridDefault===false?'hidden':'visible';document.documentElement.dataset.motion=p.reducedMotion?'reduced':'normal';}
function progressFor(p){let x=p.progress|| (p.demo?{completed:1,inprogress:1,notstarted:4}:{completed:0,inprogress:0,notstarted:6});return {...x,total:x.completed+x.inprogress+x.notstarted};}
function donut(x,size='large'){let total=x.total||1,a=x.completed/total*100,b=x.inprogress/total*100;return `<div class="donut ${size}" role="img" aria-label="${x.completed} completed, ${x.inprogress} in progress, ${x.notstarted} not started" style="background:conic-gradient(#138a74 0 ${a}%,#d2a454 ${a}% ${a+b}%,#e5ece6 ${a+b}% 100%)"><div><strong>${Math.round(a)}<small>%</small></strong><span>completed</span></div></div>`;}
function projectInsights(){let list=portfolio.records.filter(p=>p.status==='Active'),x=list.reduce((a,p)=>{let n=progressFor(p);a.completed+=n.completed;a.inprogress+=n.inprogress;a.notstarted+=n.notstarted;return a;},{completed:0,inprogress:0,notstarted:0});x.total=x.completed+x.inprogress+x.notstarted;let recent=portfolio.records.filter(p=>p.status!=='Trash').sort((a,b)=>(b.lastOpenedAt||b.updatedAt).localeCompare(a.lastOpenedAt||a.updatedAt))[0];return `<div class="project-dashboard"><section class="progress-overview"><div><div class="eyebrow">YOUR PORTFOLIO AT A GLANCE</div><h2>Keep every study moving.</h2><p>Workflow stages across ${list.length} active ${list.length===1?'project':'projects'}.</p><div class="progress-legend">${[['completed','Completed'],['inprogress','In progress'],['notstarted','Not started']].map(([k,t])=>`<div><i class="${k}"></i><span>${t}</span><strong>${x[k]}</strong></div>`).join('')}</div><span class="progress-caption">${list.some(p=>p.demo)?'Includes illustrative demo progress.':'Progress is recorded manually for each project.'}</span></div>${donut(x)}</section><section class="continue-card"><span class="eyebrow">PICK UP WHERE YOU LEFT OFF</span><span class="continue-icon">${icon('layers')}</span><h2>${esc(recent?.name||'Your next project')}</h2><p>${esc(recent?.description||'Create a project and bring your evidence together.')}</p>${recent?`<button class="primary" data-openproject="${recent.id}">Continue project ${icon('arrow')}</button>`:btn('Create project','new-project',true)}</section></div>`;}
function projectCardProgress(p){let x=progressFor(p);return `<div class="card-progress">${donut(x,'small')}<div><strong>${x.completed} of ${x.total} stages complete</strong><div class="card-progress-legend"><span><i class="inprogress"></i>${x.inprogress} in progress</span><span><i class="notstarted"></i>${x.notstarted} not started</span></div><button class="quiet progress-edit" data-progress="${p.id}">Update progress</button></div></div>`;}
function progressEditor(id){let p=portfolio.records.find(p=>p.id===id),x=progressFor(p);if(!p)return;modal('Update workflow progress',`<p class="sub">${esc(p.name)} · Six petrophysical workflow stages</p><form id="progress-form" style="margin-top:20px">${stages.map(([k,t],i)=>`<label class="field">${i+1}. ${t}<select name="${k}">${['Not started','In progress','Completed'].map(v=>`<option ${(p.stageStates?.[k]||(i<x.completed?'Completed':i<x.completed+x.inprogress?'In progress':'Not started'))===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<p class="note">This records project tracking status only. It does not approve a scientific result.</p><button class="primary" style="margin-top:18px">Save progress</button></form>`);$('#progress-form').onsubmit=e=>{e.preventDefault();p.stageStates=Object.fromEntries(new FormData(e.target));p.progress={completed:0,inprogress:0,notstarted:0};for(let v of Object.values(p.stageStates))p.progress[v==='Completed'?'completed':v==='In progress'?'inprogress':'notstarted']++;p.updatedAt=new Date().toISOString();persistPortfolio();$('#dialog').close();renderProjects();toast('Project progress updated.');};}
const helpTopics=[['Getting started','Create a project from Projects, add source metadata in Data, and review mappings before interpretation. New projects begin empty.'],['Managing projects','Use the project settings icon to edit, duplicate, archive or move a project to Trash. Archived and trashed projects can be restored. Search and favorite projects to find them quickly.'],['Reading progress charts','Green means completed, amber means in progress, and pale gray means not started. Update progress on each project card. Status tracks the work; it is separate from scientific approval.'],['Data and documents','Source files, wells and documents are separate views. File selection stores metadata in this preview. Classification, parsing, OCR and semantic search await connected services.'],['Maps and coordinate references','Switch basemaps, toggle layers and inspect wells in Map. Geometry is illustrative. A reviewed source CRS and survey reference are required for real spatial calculations.'],['Logs and QA/QC','Use the log viewer to inspect synthetic curves. In QA/QC, preview a proposal before accepting or rejecting it. Original evidence remains unchanged.'],['Methods and evidence','Each specialist workspace has parameters, evidence requirements, result states and feature specifications. A saved configuration does not run a scientific calculation.'],['Cutoffs and reservoir summaries','Separate net-reservoir and net-pay criteria. Always check the thickness basis, gross denominator, missing-data coverage and weighting definitions.'],['Settings and accessibility','Open your profile menu to find Settings. Adjust text size, density, accent and reduced motion. Defaults for units, maps, logs and reports are saved as configuration.'],['Saving and exports','Workspace drafts persist locally in this browser. Export a workspace JSON before changing device or clearing browser data. There is no server synchronization yet.'],['Accounts and privacy','Authentication and recovery screens are frontend previews. Do not use real passwords. No registration or reset email is sent.'],['Troubleshooting','If a page looks empty, check the selected project and filters. Use the demo project for illustrative data. Export drafts before resetting. Browser-local storage does not transfer between devices.']];
function openHelp(){modal('Help & keyboard shortcuts',`<div class="help-intro"><span class="help-symbol">${icon('help')}</span><div><h3>A little guidance, right where you work.</h3><p class="sub">Find a workflow topic or learn a faster way around.</p></div></div><input id="help-search" aria-label="Search help" placeholder="Search help topics…" style="width:100%;margin:18px 0"><div class="help-shortcuts"><h3>Keyboard shortcuts</h3>${[['Ctrl / ⌘ K','Search workspace'],['Alt P','All projects'],['Alt O','Project overview'],['Alt M','Map workspace'],['Alt L','Log viewer'],['Alt S','Settings'],['Shift ?','Open help'],['Escape','Close dialog or profile menu']].map(([k,t])=>`<div><span>${t}</span><kbd>${k}</kbd></div>`).join('')}</div><div id="help-topics">${helpTopics.map(([t,d])=>`<details class="help-topic"><summary>${t}</summary><p>${d}</p></details>`).join('')}</div><div class="note" style="margin-top:18px">Shortcuts are inactive while typing in form fields.</div>`);$('#help-search').oninput=e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('.help-topic').forEach(d=>d.hidden=!d.textContent.toLowerCase().includes(q));};}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#profile-popover')?.setAttribute('hidden','');$('[data-action=profile]')?.setAttribute('aria-expanded','false');return;}if(e.target.closest('input,textarea,select,[contenteditable=true]'))return;if(e.key==='?'&&!$('#dialog').open){e.preventDefault();openHelp();return;}if(e.altKey&&!$('#dialog').open){let r={p:'projects',o:'overview',m:'map',l:'logs',s:'settings'}[e.key.toLowerCase()];if(r){e.preventDefault();navigate(r);}}});
